"use client";

import { Switch as SwitchPrimitive } from "@base-ui/react/switch";
import { cva, type VariantProps } from "class-variance-authority";
import type { ReactNode } from "react";
import { cn } from "@/lib/utils";

const rockerSwitchVariants = cva(
  "rounded-lg bg-muted p-0.5 outline-none ring-1 ring-border transition-shadow focus-visible:ring-2 focus-visible:ring-ring data-disabled:cursor-not-allowed data-disabled:opacity-50 group/rocker inline-flex shrink-0 gap-0.5",
  {
    compoundVariants: [
      {
        className: "h-14 w-8 text-[0.6875rem]",
        orientation: "vertical",
        size: "default",
      },
      {
        className: "h-10 w-6 text-[0.5625rem]",
        orientation: "vertical",
        size: "sm",
      },
      {
        className: "h-8 w-14 text-[0.6875rem]",
        orientation: "horizontal",
        size: "default",
      },
      {
        className: "h-6 w-10 text-[0.5625rem]",
        orientation: "horizontal",
        size: "sm",
      },
    ],
    defaultVariants: { orientation: "vertical", size: "default" },
    variants: {
      /** Stood up, on at the top, or laid down, on at the right. */
      orientation: {
        horizontal: "flex-row-reverse",
        vertical: "flex-col",
      },
      size: {
        default: "",
        sm: "",
      },
    },
  }
);

export interface RockerSwitchProps
  extends Omit<SwitchPrimitive.Root.Props, "children" | "className">,
    VariantProps<typeof rockerSwitchVariants> {
  className?: string;
  /** What the off side reads. @default "O" */
  offLabel?: ReactNode;
  /** What the on side reads. @default "I" */
  onLabel?: ReactNode;
}

/**
 * A rocker, as on a mixer's or a synth's panel: two sides, the one pressed
 * down sunk into the panel. A switch underneath, with its role, its keyboard
 * (Space) and its form value; name it with `aria-label`.
 */
export function RockerSwitch({
  className,
  offLabel = "O",
  onLabel = "I",
  orientation,
  size,
  ...props
}: RockerSwitchProps) {
  return (
    <SwitchPrimitive.Root
      className={cn(rockerSwitchVariants({ orientation, size }), className)}
      data-orientation={orientation ?? "vertical"}
      data-size={size ?? "default"}
      data-slot="rocker-switch"
      {...props}
    >
      <span
        aria-hidden="true"
        className="rounded-md font-mono font-semibold transition-[background-color,box-shadow,color] duration-100 bg-background text-foreground shadow-sm group-data-checked/rocker:bg-transparent group-data-checked/rocker:text-primary group-data-checked/rocker:shadow-inner flex flex-1 items-center justify-center"
        data-slot="rocker-switch-on"
      >
        {onLabel}
      </span>
      <span
        aria-hidden="true"
        className="rounded-md font-mono font-semibold transition-[background-color,box-shadow,color] duration-100 text-muted-foreground shadow-inner group-data-checked/rocker:bg-background group-data-checked/rocker:text-foreground group-data-checked/rocker:shadow-sm flex flex-1 items-center justify-center"
        data-slot="rocker-switch-off"
      >
        {offLabel}
      </span>
    </SwitchPrimitive.Root>
  );
}
